-- A negative `item` in creature_loot_template is a currency id (alexkulya's convention),
-- so the column has to hold negative numbers.
ALTER TABLE `creature_loot_template` MODIFY `item` MEDIUMINT NOT NULL DEFAULT 0;

-- Currency rows of the 5.4.8 world DB (alexkulya/pandaria_5.4.8 release 2026_08_16) for loot ids
-- SFDB already has.
-- creature_loot_template currency rows added to loot ids SFDB already has: 136 loot ids, 182 rows
-- maxcount is a tinyint here: Timeless Coin on 73167 (366) and 73175 (359) is capped at 255.

